reference_solution:
def longest_target_sum_subarray(nums, target):
    earliest = {0:-1}; prefix = best = 0
    for i, value in enumerate(nums):
        prefix += value
        if prefix-target in earliest: best = max(best, i-earliest[prefix-target])
        earliest.setdefault(prefix, i)
    return best

